@if (Profile is null)
{
    <p>Loading profile...</p>
    return;
}

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        <img src="@editDisplayName" alt="Avatar" onerror="this.style.display='none'" />
        <div class="avatar-placeholder">@(string.IsNullOrEmpty(editDisplayName) ? "?" : editDisplayName[0].ToString().ToUpper())</div>
        <p class="avatar-url">@Profile.AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="editDisplayName" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="editEmail" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" rows="4" @bind="editBio"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="toast @statusClass">@statusMessage</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string? statusMessage;
    private string statusClass = "";

    protected override void OnParametersSet()
    {
        if (Profile is not null && string.IsNullOrEmpty(editDisplayName) && string.IsNullOrEmpty(statusMessage))
        {
            ResetFields();
        }
    }

    private void ResetFields()
    {
        if (Profile is null) return;
        editDisplayName = Profile.DisplayName;
        editEmail = Profile.Email;
        editBio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        if (Profile is null) return;
        var updated = Profile with { DisplayName = editDisplayName, Email = editEmail, Bio = editBio };
        await OnSave.InvokeAsync(updated);
        statusMessage = "Profile saved successfully!";
        statusClass = "toast-success";
        _ = ClearToastAsync();
    }

    private void Discard()
    {
        ResetFields();
        statusMessage = "Changes discarded.";
        statusClass = "toast-info";
        _ = ClearToastAsync();
    }

    private async Task ClearToastAsync()
    {
        await Task.Delay(3000);
        statusMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@if (Prefs is null)
{
    <p>Loading notification preferences...</p>
    return;
}

<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-row">
            <span>Email Notifications</span>
            <input type="checkbox" @bind="emailNotifications" />
        </label>
        <label class="toggle-row">
            <span>Push Notifications</span>
            <input type="checkbox" @bind="pushNotifications" />
        </label>
        <label class="toggle-row">
            <span>Weekly Digest</span>
            <input type="checkbox" @bind="weeklyDigest" />
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in allChannels)
        {
            <label class="channel-row">
                <input type="checkbox"
                       checked="@mutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool?)e.Value ?? false)" />
                <span>@channel</span>
            </label>
        }
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="SaveAsync">Save Preferences</button>
    </div>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="toast toast-success">@statusMessage</div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = new();
    private string? statusMessage;

    private static readonly string[] allChannels = ["General", "Announcements", "Engineering", "Design", "Marketing", "Support"];

    protected override void OnParametersSet()
    {
        if (Prefs is not null)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        statusMessage = "Preferences saved!";
        _ = ClearToastAsync();
    }

    private async Task ClearToastAsync()
    {
        await Task.Delay(3000);
        statusMessage = null;
        await InvokeAsync(StateHasChanged);
    }
}

@if (Settings is null)
{
    <p>Loading security settings...</p>
    return;
}

<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
            <span>Change Password</span>
            <span class="expand-icon">@(passwordPanelOpen ? "▼" : "▶")</span>
        </button>
        @if (passwordPanelOpen)
        {
            <div class="panel-body">
                <div class="form-group">
                    <label for="currentPassword">Current Password</label>
                    <input id="currentPassword" type="password" @bind="currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPassword">New Password</label>
                    <input id="newPassword" type="password" @bind="newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPassword">Confirm Password</label>
                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(passwordError))
                {
                    <p class="error-message">@passwordError</p>
                }
                @if (!string.IsNullOrEmpty(passwordSuccess))
                {
                    <p class="success-message">@passwordSuccess</p>
                }
                <button class="btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="twofa-section">
        <label class="toggle-row">
            <span>Two-Factor Authentication</span>
            <span class="status-indicator @(Settings.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                @(Settings.TwoFactorEnabled ? "Enabled" : "Disabled")
            </span>
        </label>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="meta-info">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM d, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <h3>Active Sessions</h3>
    <div class="sessions-table-container">
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Settings.Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session != Settings.Sessions.First())
                            {
                                <button class="btn-danger-sm" @onclick="() => ConfirmRevoke(session)">Revoke</button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn-danger" @onclick="RevokeSessionAsync">Yes, Revoke</button>
                    <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string current, string newPw)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private string? passwordSuccess;
    private ActiveSession? sessionToRevoke;

    private async Task UpdatePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            passwordError = "All password fields are required.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "New password and confirmation do not match.";
            return;
        }
        if (newPassword.Length < 8)
        {
            passwordError = "New password must be at least 8 characters.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        passwordSuccess = "Password updated successfully!";
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task RevokeSessionAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }
}

@if (Settings is null)
{
    <p>Loading appearance settings...</p>
    return;
}

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-option">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(selectedTheme == theme)"
                           @onchange="() => selectedTheme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size -->
    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-option">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(selectedFontSize == size)"
                           @onchange="() => selectedFontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="selectedLanguage">
            <option value="en">English</option>
            <option value="es">Español</option>
            <option value="fr">Français</option>
            <option value="de">Deutsch</option>
            <option value="ja">日本語</option>
            <option value="zh">中文</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <label class="toggle-row">
        <span>Compact Mode</span>
        <input type="checkbox" @bind="compactMode" />
    </label>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            <button class="btn-primary">Action Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn-primary" @onclick="SaveAsync">Save</button>
    </div>

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="toast toast-success">@statusMessage</div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

