@page "/settings"
@using sv_dea00f7223984b818d930e362fcd85f2.Components.Pages.Settings
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@profile" OnSave="SaveProfileAsync" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@notificationPrefs" OnSave="SaveNotificationsAsync" />
                break;
            case "Security":
                <SecuritySection Settings="@securitySettings"
                                 OnChangePassword="ChangePasswordAsync"
                                 OnRevokeSession="RevokeSessionAsync" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@appearanceSettings" OnSave="SaveAppearanceAsync" />
                break;
        }
    </main>
</div>

@code {
    private string activeSection = "Profile";
    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadSectionDataAsync(activeSection);
    }

    private async Task SetActiveSection(string section)
    {
        activeSection = section;
        await LoadSectionDataAsync(section);
    }

    private async Task LoadSectionDataAsync(string section)
    {
        switch (section)
        {
            case "Profile" when profile is null:
                profile = await SettingsService.GetProfileAsync();
                break;
            case "Notifications" when notificationPrefs is null:
                notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
                break;
            case "Security" when securitySettings is null:
                securitySettings = await SettingsService.GetSecuritySettingsAsync();
                break;
            case "Appearance" when appearanceSettings is null:
                appearanceSettings = await SettingsService.GetAppearanceAsync();
                break;
        }
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task ChangePasswordAsync((string current, string newPw) args)
    {
        await SettingsService.ChangePasswordAsync(args.current, args.newPw);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

/* Sidebar */
::deep .settings-sidebar {
    width: 240px;
    background: var(--bs-gray-100, #f8f9fa);
    border-right: 1px solid var(--bs-border-color, #dee2e6);
    padding: 1rem 0;
}

::deep .settings-sidebar nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

::deep .settings-sidebar nav ul li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    transition: background-color 0.15s, border-left-color 0.15s;
    border-left: 3px solid transparent;
}

::deep .settings-sidebar nav ul li:hover {
    background: var(--bs-gray-200, #e9ecef);
}

::deep .settings-sidebar nav ul li.active {
    background: var(--bs-primary-bg-subtle, #cfe2ff);
    border-left-color: var(--bs-primary, #0d6efd);
    font-weight: 600;
}

::deep .sidebar-icon {
    font-size: 1.2rem;
}

/* Section styling */
::deep .settings-section h2 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
}

::deep .settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
}

/* Form elements */
::deep .form-group {
    margin-bottom: 1.25rem;
}

::deep .form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
}

::deep .form-group input[type="text"],
::deep .form-group input[type="email"],
::deep .form-group input[type="password"],
::deep .form-group textarea,
::deep .form-group select {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.375rem;
    font-size: 1rem;
}

::deep .form-group textarea {
    resize: vertical;
}

::deep .form-group select {
    appearance: auto;
}

/* Buttons */
::deep .form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

::deep .btn-primary {
    background: var(--bs-primary, #0d6efd);
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-primary:hover {
    background: var(--bs-primary-hover, #0b5ed7);
}

::deep .btn-secondary {
    background: var(--bs-gray-200, #e9ecef);
    color: var(--bs-body-color, #212529);
    border: 1px solid var(--bs-border-color, #dee2e6);
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-secondary:hover {
    background: var(--bs-gray-300, #dee2e6);
}

::deep .btn-danger {
    background: var(--bs-danger, #dc3545);
    color: white;
    border: none;
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    cursor: pointer;
    font-size: 0.9rem;
}

::deep .btn-danger-sm {
    background: var(--bs-danger, #dc3545);
    color: white;
    border: none;
    padding: 0.25rem 0.75rem;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 0.8rem;
}

/* Toggle rows */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

::deep .toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: var(--bs-gray-100, #f8f9fa);
    border-radius: 0.375rem;
    cursor: pointer;
}

::deep .toggle-row input[type="checkbox"] {
    width: 1.25rem;
    height: 1.25rem;
    cursor: pointer;
}

/* Channel list */
::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

::deep .channel-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 1rem;
    cursor: pointer;
}

::deep .channel-row:hover {
    background: var(--bs-gray-100, #f8f9fa);
    border-radius: 0.25rem;
}

/* Toast messages */
::deep .toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

::deep .toast-success {
    background: var(--bs-success-bg-subtle, #d1e7dd);
    color: var(--bs-success-text-emphasis, #0a3622);
    border: 1px solid var(--bs-success-border-subtle, #a3cfbb);
}

::deep .toast-info {
    background: var(--bs-info-bg-subtle, #cff4fc);
    color: var(--bs-info-text-emphasis, #055160);
    border: 1px solid var(--bs-info-border-subtle, #9eeaf9);
}

/* Avatar */
::deep .avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

::deep .avatar-preview img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid var(--bs-border-color, #dee2e6);
}

::deep .avatar-placeholder {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: var(--bs-primary, #0d6efd);
    color: white;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    font-weight: 600;
}

::deep .avatar-url {
    font-size: 0.8rem;
    color: var(--bs-secondary, #6c757d);
    margin-top: 0.5rem;
    word-break: break-all;
}

/* Expandable panel */
::deep .expandable-panel {
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.375rem;
    margin-bottom: 1.5rem;
}

::deep .panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: var(--bs-gray-100, #f8f9fa);
    border: none;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
    border-radius: 0.375rem;
}

::deep .panel-header:hover {
    background: var(--bs-gray-200, #e9ecef);
}

::deep .panel-body {
    padding: 1rem;
    border-top: 1px solid var(--bs-border-color, #dee2e6);
}

/* Status indicators */
::deep .status-indicator {
    padding: 0.25rem 0.75rem;
    border-radius: 1rem;
    font-size: 0.8rem;
    font-weight: 500;
}

::deep .status-enabled {
    background: var(--bs-success-bg-subtle, #d1e7dd);
    color: var(--bs-success-text-emphasis, #0a3622);
}

::deep .status-disabled {
    background: var(--bs-warning-bg-subtle, #fff3cd);
    color: var(--bs-warning-text-emphasis, #664d03);
}

::deep .meta-info {
    font-size: 0.85rem;
    color: var(--bs-secondary, #6c757d);
    margin-top: 0.5rem;
}

::deep .current-badge {
    font-size: 0.8rem;
    color: var(--bs-success, #198754);
    font-weight: 500;
}

/* Sessions table */
::deep .sessions-table-container {
    overflow-x: auto;
}

::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid var(--bs-border-color, #dee2e6);
}

::deep .sessions-table th {
    font-weight: 600;
    background: var(--bs-gray-100, #f8f9fa);
}

/* Error / Success messages */
::deep .error-message {
    color: var(--bs-danger, #dc3545);
    font-size: 0.9rem;
    margin: 0.5rem 0;
}

::deep .success-message {
    color: var(--bs-success, #198754);
    font-size: 0.9rem;
    margin: 0.5rem 0;
}

/* Modal */
::deep .modal-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .modal-dialog {
    background: white;
    border-radius: 0.5rem;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
}

::deep .modal-dialog h4 {
    margin-bottom: 0.75rem;
}

::deep .modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Radio groups */
::deep .radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

::deep .radio-option {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Appearance preview */
::deep .preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.5rem;
    transition: all 0.2s;
}

::deep .preview-area h4 {
    margin-bottom: 0.5rem;
}

::deep .preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid var(--bs-border-color, #dee2e6);
    border-radius: 0.375rem;
}

::deep .preview-dark {
    background: #1a1a2e;
    color: #e0e0e0;
    border-color: #333;
}

::deep .preview-dark .preview-card {
    background: #16213e;
    border-color: #444;
}

::deep .preview-light {
    background: #ffffff;
    color: #212529;
}

::deep .preview-system {
    background: #f0f0f0;
    color: #212529;
}

::deep .preview-font-small {
    font-size: 0.8rem;
}

::deep .preview-font-medium {
    font-size: 1rem;
}

::deep .preview-font-large {
    font-size: 1.2rem;
}

::deep .preview-area.compact {
    padding: 0.75rem;
}

::deep .preview-area.compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

/* 2FA section */
::deep .twofa-section {
    margin-bottom: 1.5rem;
}

